import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0
    times = sorted({t for start, end, _pay in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    m = len(times)
    graph: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)
    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    INF = 10**30
    potential = [INF] * m
    potential[0] = 0
    for u in range(m):
        if potential[u] >= INF:
            continue
        for v, cap, cost, _rev in graph[u]:
            if cap > 0 and potential[u] + cost < potential[v]:
                potential[v] = potential[u] + cost

    sink = m - 1
    flown = 0
    total_cost = 0
    while flown < k:
        dist = [INF] * m
        dist[0] = 0
        prev_v = [-1] * m
        prev_e = [-1] * m
        heap = [(0, 0)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            for ei, (v, cap, cost, _rev) in enumerate(graph[u]):
                if cap <= 0:
                    continue
                nd = d + cost + potential[u] - potential[v]
                if nd < dist[v]:
                    dist[v] = nd
                    prev_v[v] = u
                    prev_e[v] = ei
                    heapq.heappush(heap, (nd, v))
        if dist[sink] >= INF:
            break
        for i in range(m):
            if dist[i] < INF:
                potential[i] += dist[i]
        add = k - flown
        v = sink
        while v != 0:
            u = prev_v[v]
            add = min(add, graph[u][prev_e[v]][1])
            v = u
        v = sink
        while v != 0:
            u = prev_v[v]
            edge = graph[u][prev_e[v]]
            edge[1] -= add
            graph[v][edge[3]][1] += add
            total_cost += add * edge[2]
            v = u
        flown += add
    return -total_cost
